  1→import { useEffect, useState } from "react";
  2→import type { LoaderFunctionArgs, ActionFunctionArgs } from "react-router";
  3→import { useLoaderData, useFetcher, useNavigate } from "react-router";
  4→import { useAppBridge } from "@shopify/app-bridge-react";
  5→import {
  6→  Page,
  7→  Layout,
  8→  Card,
  9→  BlockStack,
 10→  InlineStack,
 11→  Text,
 12→  Badge,
 13→  Button,
 14→  ButtonGroup,
 15→  Banner,
 16→  Box,
 17→  Divider,
 18→  InlineGrid,
 19→  Modal,
 20→  ProgressBar,
 21→  TextField,
 22→  Select,
 23→  Icon,
 24→} from "@shopify/polaris";
 25→import { SearchIcon } from "@shopify/polaris-icons";
 26→import { authenticate } from "../shopify.server";
 27→import db from "../db.server";
 28→import { getPlan, canCreateChart } from "../lib/plans";
 29→import { SIZE_CHART_TEMPLATES, getCategories } from "../lib/templates";
 30→
 31→export const loader = async ({ request }: LoaderFunctionArgs) => {
 32→  const { session } = await authenticate.admin(request);
 33→  const shop = session.shop;
 34→
 35→  const [charts, subscription] = await Promise.all([
 36→    db.sizeChart.findMany({
 37→      where: { shop },
 38→      orderBy: { updatedAt: "desc" },
 39→      include: { assignments: true },
 40→    }),
 41→    db.subscription.findUnique({ where: { shop } }),
 42→  ]);
 43→
 44→  const plan = getPlan(subscription?.planId ?? "free");
 45→  const templates = SIZE_CHART_TEMPLATES.map((t) => ({
 46→    name: t.name,
 47→    category: t.category,
 48→    gender: t.gender,
 49→    rowCount: t.data.rows.length,
 50→  }));
 51→  const categories = getCategories();
 52→
 53→  return {
 54→    charts,
 55→    plan,
 56→    templates,
 57→    categories,
 58→    canCreate: canCreateChart(plan.id, charts.length),
 59→  };
 60→};
 61→
 62→export const action = async ({ request }: ActionFunctionArgs) => {
 63→  const { session } = await authenticate.admin(request);
 64→  const shop = session.shop;
 65→  const formData = await request.formData();
 66→  const intent = formData.get("intent") as string;
 67→
 68→  try {
 69→    switch (intent) {
 70→      case "create-from-template": {
 71→        const templateName = formData.get("templateName") as string;
 72→        const template = SIZE_CHART_TEMPLATES.find((t) => t.name === templateName);
 73→        if (!template) return { error: "Template not found" };
 74→
 75→        const subscription = await db.subscription.findUnique({ where: { shop } });
 76→        const plan = getPlan(subscription?.planId ?? "free");
 77→        const chartCount = await db.sizeChart.count({ where: { shop } });
 78→        if (!canCreateChart(plan.id, chartCount)) {
 79→          return {
 80→            error: `Free plan allows max ${plan.limits.maxCharts} charts. Upgrade to create more.`,
 81→          };
 82→        }
 83→
 84→        let name = template.name;
 85→        const existing = await db.sizeChart.findUnique({
 86→          where: { shop_name: { shop, name } },
 87→        });
 88→        if (existing) name = `${template.name} (${Date.now().toString(36)})`;
 89→
 90→        const created = await db.sizeChart.create({
 91→          data: {
 92→            shop,
 93→            name,
 94→            category: template.category,
 95→            data: JSON.stringify(template.data),
 96→            status: "active",
 97→          },
 98→        });
 99→        return { ok: true, message: `"${name}" created successfully`, redirectId: created.id };
100→      }
101→
102→      case "create-blank": {
103→        const name = (formData.get("name") as string) || "Untitled Size Chart";
104→        const category = (formData.get("category") as string) || "general";
105→
106→        const subscription = await db.subscription.findUnique({ where: { shop } });
107→        const plan = getPlan(subscription?.planId ?? "free");
108→        const chartCount = await db.sizeChart.count({ where: { shop } });
109→        if (!canCreateChart(plan.id, chartCount)) {
110→          return {
111→            error: `Free plan allows max ${plan.limits.maxCharts} charts. Upgrade to create more.`,
112→          };
113→        }
114→
115→        let uniqueName = name;
116→        const existing = await db.sizeChart.findUnique({
117→          where: { shop_name: { shop, name } },
118→        });
119→        if (existing) uniqueName = `${name} (${Date.now().toString(36)})`;
120→
121→        const defaultData = {
122→          headers: ["Size", "Chest", "Waist", "Hips"],
123→          units: { default: "in", available: ["in", "cm"] },
124→          rows: [
125→            { Size: "S", Chest: "", Waist: "", Hips: "" },
126→            { Size: "M", Chest: "", Waist: "", Hips: "" },
127→            { Size: "L", Chest: "", Waist: "", Hips: "" },
128→          ],
129→        };
130→
131→        const created = await db.sizeChart.create({
132→          data: {
133→            shop,
134→            name: uniqueName,
135→            category,
136→            data: JSON.stringify(defaultData),
137→            status: "draft",
138→          },
139→        });
140→        return { ok: true, message: `"${uniqueName}" created`, redirectId: created.id };
141→      }
142→
143→      case "delete": {
144→        const id = formData.get("id") as string;
145→        await db.sizeChart.deleteMany({ where: { id, shop } });
146→        return { ok: true, message: "Chart deleted" };
147→      }
148→
149→      case "import-csv": {
150→        const csvRaw = formData.get("csvData") as string;
151→        const chartName = (formData.get("name") as string) || "Imported Size Chart";
152→        const category = (formData.get("category") as string) || "general";
153→
154→        if (!csvRaw?.trim()) return { error: "CSV data is required" };
155→
156→        const subscription = await db.subscription.findUnique({ where: { shop } });
157→        const plan = getPlan(subscription?.planId ?? "free");
158→        const chartCount = await db.sizeChart.count({ where: { shop } });
159→        if (!canCreateChart(plan.id, chartCount)) {
160→          return { error: `Free plan allows max ${plan.limits.maxCharts} charts. Upgrade to create more.` };
161→        }
162→
163→        // Parse CSV
164→        const lines = csvRaw.trim().split(/\r?\n/).filter((l) => l.trim());
165→        if (lines.length < 2) return { error: "CSV must have a header row and at least one data row." };
166→
167→        const parseRow = (line: string): string[] => {
168→          const result: string[] = [];
169→          let current = "";
170→          let inQuotes = false;
171→          for (let i = 0; i < line.length; i++) {
172→            const ch = line[i];
173→            if (ch === '"') {
174→              if (inQuotes && line[i + 1] === '"') { current += '"'; i++; }
175→              else { inQuotes = !inQuotes; }
176→            } else if (ch === "," && !inQuotes) {
177→              result.push(current.trim());
178→              current = "";
179→            } else {
180→              current += ch;
181→            }
182→          }
183→          result.push(current.trim());
184→          return result;
185→        };
186→
187→        const headers = parseRow(lines[0]);
188→        if (headers.length < 1) return { error: "Could not parse CSV headers." };
189→
190→        const rows = lines.slice(1).map((line) => {
191→          const cells = parseRow(line);
192→          const row: Record<string, string> = {};
193→          headers.forEach((h, i) => { row[h] = cells[i] ?? ""; });
194→          return row;
195→        });
196→
197→        const data = {
198→          headers,
199→          units: { default: "in", available: ["in", "cm"] },
200→          rows,
201→        };
202→
203→        let uniqueName = chartName;
204→        const existingName = await db.sizeChart.findUnique({ where: { shop_name: { shop, name: chartName } } });
205→        if (existingName) uniqueName = `${chartName} (${Date.now().toString(36)})`;
206→
207→        const created = await db.sizeChart.create({
208→          data: { shop, name: uniqueName, category, data: JSON.stringify(data), status: "draft" },
209→        });
210→        return { ok: true, message: `Imported "${uniqueName}"`, redirectId: created.id };
211→      }
212→
213→      case "duplicate": {
214→        const sourceId = formData.get("id") as string;
215→        const source = await db.sizeChart.findFirst({ where: { id: sourceId, shop } });
216→        if (!source) return { error: "Chart not found" };
217→
218→        const subscription = await db.subscription.findUnique({ where: { shop } });
219→        const plan = getPlan(subscription?.planId ?? "free");
220→        const chartCount = await db.sizeChart.count({ where: { shop } });
221→        if (!canCreateChart(plan.id, chartCount)) {
222→          return { error: "Chart limit reached. Upgrade your plan." };
223→        }
224→
225→        const newName = `${source.name} (Copy)`;
226→        await db.sizeChart.create({
227→          data: {
228→            shop,
229→            name: newName,
230→            type: source.type,
231→            category: source.category,
232→            data: source.data,
233→            status: "draft",
234→          },
235→        });
236→        return { ok: true, message: `Duplicated as "${newName}"` };
237→      }
238→
239→      case "toggle-status": {
240→        const chartId = formData.get("id") as string;
241→        const chart = await db.sizeChart.findFirst({ where: { id: chartId, shop } });
242→        if (!chart) return { error: "Chart not found" };
243→
244→        const newStatus = chart.status === "active" ? "draft" : "active";
245→        await db.sizeChart.update({ where: { id: chartId }, data: { status: newStatus } });
246→        return {
247→          ok: true,
248→          message: `Chart ${newStatus === "active" ? "published" : "unpublished"}`,
249→        };
250→      }
251→
252→      default:
253→        return { error: "Unknown action" };
254→    }
255→  } catch (error) {
256→    const message = error instanceof Error ? error.message : "An unexpected error occurred";
257→    if (message.includes("Unique constraint")) {
258→      return { error: "A chart with this name already exists." };
259→    }
260→    return { error: message };
261→  }
262→};
