333→function TemplatePicker({ templates, categories, isLoading, fetcher }: TemplateSectionProps) {
334→  const [selectedCategory, setSelectedCategory] = useState<string>("all");
335→
336→  const filteredTemplates = selectedCategory === "all"
337→    ? templates
338→    : templates.filter((t) => t.category === selectedCategory);
339→
340→  return (
341→    <BlockStack gap="400">
342→      {/* Category filter */}
343→      <ButtonGroup variant="segmented">
344→        <Button
345→          variant={selectedCategory === "all" ? "primary" : undefined}
346→          onClick={() => setSelectedCategory("all")}
347→        >
348→          All
349→        </Button>
350→        {categories.map((cat) => (
351→          <Button
352→            key={cat}
353→            variant={selectedCategory === cat ? "primary" : undefined}
354→            onClick={() => setSelectedCategory(cat)}
355→          >
356→            {CATEGORY_ICONS[cat] ?? "📏"} {CATEGORY_LABELS[cat] ?? cat}
357→          </Button>
358→        ))}
359→      </ButtonGroup>
360→
361→      {/* Blank chart */}
362→      <Card>
363→        <InlineStack gap="400" align="space-between" blockAlign="center">
