366→            <Text as="p" variant="bodyMd" tone="subdued">
367→              Start with an empty table — add your own columns and sizes
368→            </Text>
369→          </BlockStack>
370→          <fetcher.Form method="post">
371→            <input type="hidden" name="intent" value="create-blank" />
372→            <input type="hidden" name="name" value="Untitled Size Chart" />
373→            <input type="hidden" name="category" value="general" />
374→            <Button submit loading={isLoading}>Create blank</Button>
375→          </fetcher.Form>
376→        </InlineStack>
377→      </Card>
378→
379→      {/* Template grid */}
380→      {filteredTemplates.length > 0 ? (
381→        <InlineGrid columns={{ xs: 1, sm: 2, md: 3 }} gap="400">
382→          {filteredTemplates.map((template) => (
383→            <Card key={template.name}>
384→              <BlockStack gap="200">
385→                <InlineStack gap="200" blockAlign="center">
386→                  <Text as="span" variant="bodyMd">{CATEGORY_ICONS[template.category] ?? "📏"}</Text>
387→                  <Text as="p" variant="bodyMd" fontWeight="bold">{template.name}</Text>
388→                </InlineStack>
389→                <InlineStack gap="200">
390→                  <Badge tone="info">{CATEGORY_LABELS[template.category] ?? template.category}</Badge>
391→                  <Text as="span" variant="bodyMd" tone="subdued">{template.rowCount} sizes</Text>
392→                </InlineStack>
393→                <fetcher.Form method="post">
394→                  <input type="hidden" name="intent" value="create-from-template" />
395→                  <input type="hidden" name="templateName" value={template.name} />
396→                  <Button variant="primary" submit loading={isLoading}>
397→                    Use template
398→                  </Button>
399→                </fetcher.Form>
400→              </BlockStack>
401→            </Card>
402→          ))}
403→        </InlineGrid>
404→      ) : (
405→        <Text as="p" variant="bodyMd" tone="subdued">No templates in this category.</Text>
406→      )}
407→    </BlockStack>
