415→export default function SizeCharts() {
416→  const { charts, plan, templates, categories, canCreate } =
417→    useLoaderData<typeof loader>();
418→  const fetcher = useFetcher<typeof action>();
419→  const shopify = useAppBridge();
420→  const navigate = useNavigate();
421→
422→  const [showTemplates, setShowTemplates] = useState(false);
423→  const [showImport, setShowImport] = useState(false);
424→  const [importName, setImportName] = useState("Imported Size Chart");
425→  const [importCategory, setImportCategory] = useState("general");
426→  const [importCsvText, setImportCsvText] = useState("");
427→  const [statusFilter, setStatusFilter] = useState<"all" | "active" | "draft">("all");
428→  const [categoryFilter, setCategoryFilter] = useState("all");
429→  const [searchQuery, setSearchQuery] = useState("");
430→
431→  const isLoading = fetcher.state !== "idle";
432→
433→  useEffect(() => {
434→    if (!fetcher.data) return;
435→    const data = fetcher.data as ActionData;
436→    if ("ok" in data && data.ok) {
437→      shopify.toast.show(data.message);
438→      if ("redirectId" in data && data.redirectId) {
439→        window.location.href = `/app/size-charts/${data.redirectId}`;
440→      } else {
441→        setShowTemplates(false);
442→        setShowImport(false);
443→        setImportCsvText("");
444→        setImportName("Imported Size Chart");
445→      }
446→    } else if ("error" in data) {
447→      shopify.toast.show(data.error, { isError: true });
448→    }
449→  }, [fetcher.data, shopify]);
450→
451→  const filteredCharts = charts.filter((chart) => {
452→    const matchesStatus = statusFilter === "all" || chart.status === statusFilter;
453→    const matchesCategory = categoryFilter === "all" || chart.category === categoryFilter;
454→    const matchesSearch =
455→      searchQuery.trim() === "" ||
456→      chart.name.toLowerCase().includes(searchQuery.toLowerCase());
457→    return matchesStatus && matchesCategory && matchesSearch;
458→  });
459→
460→  const publishedCount = charts.filter((c) => c.status === "active").length;
461→  const activeFilteredCount = charts.filter((c) => c.status === "active").length;
462→  const draftFilteredCount = charts.filter((c) => c.status === "draft").length;
463→  const maxCharts = plan.limits.maxCharts;
464→  const isFreePlan = plan.id === "free";
465→
466→  const progressPct =
467→    maxCharts > 0 ? Math.min(100, Math.round((publishedCount / maxCharts) * 100)) : 0;
468→  const progressTone: "primary" | "critical" =
469→    publishedCount >= maxCharts && maxCharts > 0 ? "critical" : "primary";
470→
471→  const categoryFilterOptions = [
472→    { label: "All categories", value: "all" },
473→    ...categories.map((cat) => ({ label: CATEGORY_LABELS[cat] ?? cat, value: cat })),
474→  ];
475→
476→  function clearFilters() {
477→    setStatusFilter("all");
478→    setCategoryFilter("all");
479→    setSearchQuery("");
480→  }
481→
482→  return (
483→    <Page
484→      title="Size Charts"
485→      backAction={{ onAction: () => navigate("/app") }}
486→      primaryAction={
487→        <Button
488→          variant="primary"
489→          onClick={() => setShowTemplates(!showTemplates)}
490→          disabled={!canCreate || isLoading}
491→        >
492→          {canCreate
493→            ? showTemplates
494→              ? "Cancel"
495→              : "Create chart"
496→            : `Limit reached (${plan.limits.maxCharts})`}
497→        </Button>
498→      }
499→      secondaryActions={[
500→        {
501→          content: "Import CSV",
502→          onAction: () => {
503→            setShowImport(!showImport);
504→            setShowTemplates(false);
505→          },
506→        },
507→      ]}
508→    >
509→      <Layout>
510→
511→        {/* ================================================================ */}
512→        {/* PLAN LIMIT BANNER                                                 */}
513→        {/* ================================================================ */}
514→        {!canCreate && (
515→          <Layout.Section>
516→            <Banner tone="warning" title="Chart limit reached">
517→              <BlockStack gap="200">
518→                <Text as="p" variant="bodyMd">
519→                  You have reached the {plan.limits.maxCharts}-chart limit on the{" "}
520→                  {plan.name} plan. Upgrade to Starter for unlimited charts with no
521→                  hidden fees.
522→                </Text>
523→                <Button variant="primary" url="/app/pricing">Upgrade plan</Button>
524→              </BlockStack>
525→            </Banner>
526→          </Layout.Section>
527→        )}
528→
529→        {/* ================================================================ */}
530→        {/* TEMPLATE PICKER MODAL                                             */}
531→        {/* ================================================================ */}
532→        <Modal
533→          open={showTemplates}
534→          onClose={() => setShowTemplates(false)}
535→          title="Create a size chart"
536→        >
537→          <Modal.Section>
538→            <BlockStack gap="200">
539→              <Text as="p" variant="bodyMd" tone="subdued">
540→                Start from scratch or choose a pre-filled template
541→              </Text>
542→            </BlockStack>
543→          </Modal.Section>
544→          <Modal.Section>
545→            <TemplatePicker
546→              templates={templates}
547→              categories={categories}
548→              isLoading={isLoading}
549→              onClose={() => setShowTemplates(false)}
550→              fetcher={fetcher}
551→            />
552→          </Modal.Section>
553→        </Modal>
554→
555→        {/* ================================================================ */}
556→        {/* CSV IMPORT MODAL                                                  */}
557→        {/* ================================================================ */}
