 248→function formatDate(iso: string): string {
 249→  return new Date(iso).toLocaleDateString("en-US", {
 250→    month: "short",
 251→    day: "numeric",
 252→    year: "numeric",
 253→    hour: "2-digit",
 254→    minute: "2-digit",
 255→  });
 256→}
 257→
 258→function makeDefaultData(): ChartData {
 259→  return {
 260→    headers: ["Size", "Chest", "Waist", "Hips"],
 261→    units: { default: "in", available: ["in", "cm"] },
 262→    rows: [
 263→      { Size: "S", Chest: "", Waist: "", Hips: "" },
 264→      { Size: "M", Chest: "", Waist: "", Hips: "" },
 265→      { Size: "L", Chest: "", Waist: "", Hips: "" },
 266→    ],
 267→  };
 268→}
 269→
 270→function parseChartData(raw: string): ChartData {
 271→  try {
 272→    const parsed = JSON.parse(raw) as ChartData;
 273→    if (
 274→      Array.isArray(parsed.headers) &&
 275→      parsed.units &&
 276→      Array.isArray(parsed.rows)
 277→    ) {
 278→      return parsed;
 279→    }
 280→  } catch {
 281→    // fall through
 282→  }
 283→  return makeDefaultData();
 284→}
