 644→type LoaderData = Awaited<ReturnType<typeof loader>>;
 645→type ActiveTab = "chart" | "assignments" | "position" | "recommendation" | "settings";
 646→
 647→export default function SizeChartEditor() {
 648→  const loaderData = useLoaderData<typeof loader>() as LoaderData;
 649→  const { chart, assignments: initialAssignments, isNew } = loaderData;
 650→  const navigate = useNavigate();
 651→
 652→  const saveFetcher = useFetcher<typeof action>();
 653→  const statusFetcher = useFetcher<typeof action>();
 654→  const assignmentFetcher = useFetcher<typeof action>();
 655→  const shopify = useAppBridge();
 656→
 657→  const [activeTab, setActiveTab] = useState<ActiveTab>("chart");
 658→  const [name, setName] = useState(chart?.name ?? "Untitled Size Chart");
 659→  const [category, setCategory] = useState(chart?.category ?? "general");
 660→  const [status, setStatus] = useState(chart?.status ?? "draft");
 661→  const [chartData, setChartData] = useState<ChartData>(
 662→    chart ? parseChartData(chart.data) : makeDefaultData(),
 663→  );
 664→  const [assignments, setAssignments] =
 665→    useState<Assignment[]>(initialAssignments);
 666→  const [newAssignmentType, setNewAssignmentType] = useState("product");
 667→  const [newAssignmentValue, setNewAssignmentValue] = useState("");
 668→
 669→  // Position settings (stored in chartData.displaySettings)
 670→  const _parsedSettings = chart ? parseChartData(chart.data).displaySettings : undefined;
 671→  const [priority, setPriority] = useState(_parsedSettings?.priority ?? 1);
 672→  const [countries, setCountries] = useState<"all" | "selected">(_parsedSettings?.countries ?? "all");
 673→  const [selectedCountries, setSelectedCountries] = useState(_parsedSettings?.selectedCountries ?? "");
 674→  const [buttonPosition, setButtonPosition] = useState<"floating" | "above_desc" | "below_desc">(_parsedSettings?.buttonPosition ?? "floating");
 675→  const [recommendationEnabled, setRecommendationEnabled] = useState(
 676→    chart ? (parseChartData(chart.data).recommendationEnabled ?? false) : false,
 677→  );
 678→
 679→  const isSaving = saveFetcher.state !== "idle";
 680→  const isTogglingStatus = statusFetcher.state !== "idle";
 681→
 682→  // Check for ?saved=1 on mount (after redirect from new chart creation)
 683→  useEffect(() => {
 684→    if (typeof window !== "undefined") {
 685→      const url = new URL(window.location.href);
