 691→    }
 692→  }, [shopify]);
 693→
 694→  // Save feedback
 695→  useEffect(() => {
 696→    if (!saveFetcher.data) return;
 697→    const data = saveFetcher.data;
 698→    if ("ok" in data && data.ok) {
 699→      shopify.toast.show(data.message ?? "Saved");
 700→    } else if ("error" in data) {
 701→      shopify.toast.show(data.error ?? "An error occurred", { isError: true });
 702→    }
 703→  }, [saveFetcher.data, shopify]);
 704→
 705→  // Status toggle feedback
 706→  useEffect(() => {
 707→    if (!statusFetcher.data) return;
 708→    const data = statusFetcher.data;
 709→    if ("ok" in data && data.ok) {
 710→      shopify.toast.show(data.message ?? "Status updated");
 711→      if ("newStatus" in data && typeof data.newStatus === "string") {
 712→        setStatus(data.newStatus);
 713→      }
 714→    } else if ("error" in data) {
 715→      shopify.toast.show(data.error ?? "An error occurred", { isError: true });
 716→    }
 717→  }, [statusFetcher.data, shopify]);
 718→
 719→  // Assignment feedback
