136→        productId: productId ?? null,
137→        metadata: metadataJson,
138→      },
139→    });
140→
141→    return Response.json({ ok: true }, { headers: CORS_HEADERS });
142→  } catch {
143→    // Non-critical: tracking failures should not break the storefront
144→    // Still return 200 to avoid retries from the widget
145→    return Response.json({ ok: true }, { headers: CORS_HEADERS });
146→  }
147→};
