 909→    var timer = setTimeout(function () { ctrl.abort(); }, timeoutMs);
 910→    var fetchOpts = Object.assign({ signal: ctrl.signal }, opts || {});
 911→    return fetch(url, fetchOpts)
 912→      .then(function (r) {
 913→        clearTimeout(timer);
 914→        return r.ok ? r.json() : null;
 915→      })
 916→      .catch(function () {
 917→        clearTimeout(timer);
 918→        return null;
 919→      });
 920→  }
