1120→  function renderTable(data, unit) {
1121→    if (!tableHead || !tableBody) return;
1122→    var headers = data.headers || [];
1123→    var rows    = data.rows    || [];
1124→    var isMetric = unit === 'cm';
1125→    var convFactor = 2.54;
1126→
1127→    // Build header row
1128→    var headTr = '<tr>';
1129→    headers.forEach(function (h) {
1130→      headTr += '<th scope="col">' + escapeHtml(h) + '</th>';
1131→    });
1132→    headTr += '</tr>';
1133→    tableHead.innerHTML = headTr;
1134→
1135→    // Build body rows
1136→    var bodyHtml = '';
1137→    rows.forEach(function (row) {
1138→      bodyHtml += '<tr>';
1139→      headers.forEach(function (h, i) {
1140→        var cell = row[h] !== undefined ? row[h] : '';
1141→        // Convert numeric measurement columns when unit changes
1142→        // Skip first column (Size label) and non-numeric cells
1143→        if (i > 0 && isMetric) {
1144→          var num = parseFloat(cell);
1145→          if (!isNaN(num)) {
1146→            // Check if source unit is 'in'; if chart is already cm, skip
1147→            var srcUnit = (data.units && data.units.default) || 'in';
1148→            if (srcUnit === 'in') {
1149→              cell = (num * convFactor).toFixed(1);
1150→            }
1151→          }
1152→        } else if (i > 0 && !isMetric) {
1153→          var num2 = parseFloat(cell);
1154→          if (!isNaN(num2)) {
1155→            var srcUnit2 = (data.units && data.units.default) || 'in';
1156→            if (srcUnit2 === 'cm') {
1157→              cell = (num2 / convFactor).toFixed(1);
1158→            }
1159→          }
1160→        }
1161→        var tag = i === 0 ? 'th scope="row"' : 'td';
1162→        var closeTag = i === 0 ? 'th' : 'td';
1163→        bodyHtml += '<' + tag + '>' + escapeHtml(String(cell)) + '</' + closeTag + '>';
1164→      });
1165→      bodyHtml += '</tr>';
1166→    });
1167→    tableBody.innerHTML = bodyHtml;
1168→
1169→    // Show scroll hint only when table overflows container
1170→    if (scrollHint) {
1171→      var tableEl = tableBody.closest('.scr-table-scroll');
1172→      if (tableEl && tableEl.scrollWidth > tableEl.clientWidth) {
1173→        scrollHint.style.display = '';
1174→      } else {
1175→        scrollHint.style.display = 'none';
1176→      }
1177→    }
1178→  }
