1559→        uToggle.removeAttribute('hidden');
1560→        var inlineUnit = data.units.default || 'in';
1561→        uToggle.addEventListener('click', function (e2) {
1562→          var b = e2.target.closest('.scr-unit-btn');
1563→          if (!b) return;
1564→          inlineUnit = b.dataset.unit;
1565→          uToggle.querySelectorAll('.scr-unit-btn').forEach(function (btn2) {
1566→            btn2.classList.toggle('scr-unit-btn--active', btn2.dataset.unit === inlineUnit);
1567→          });
1568→          if (head && body) renderInlineTable(data, inlineUnit, head, body);
1569→        });
1570→      }
1571→      trackEvent('view', { sizeChartId: data.id });
1572→    });
1573→  }
1574→
1575→  function renderInlineTable(data, unit, head, body) {
1576→    var isMetric = unit === 'cm';
1577→    var conv = 2.54;
1578→    var srcUnit = (data.units && data.units.default) || 'in';
1579→    var hRow = '<tr>';
1580→    (data.headers || []).forEach(function (h) { hRow += '<th scope="col">' + escapeHtml(h) + '</th>'; });
1581→    hRow += '</tr>';
1582→    head.innerHTML = hRow;
1583→    var bHtml = '';
1584→    (data.rows || []).forEach(function (row) {
1585→      bHtml += '<tr>';
1586→      (data.headers || []).forEach(function (h, i) {
1587→        var cell = row[h] !== undefined ? row[h] : '';
1588→        if (i > 0) {
1589→          var num = parseFloat(cell);
1590→          if (!isNaN(num)) {
1591→            if (isMetric && srcUnit === 'in') cell = (num * conv).toFixed(1);
1592→            else if (!isMetric && srcUnit === 'cm') cell = (num / conv).toFixed(1);
1593→          }
1594→        }
1595→        var tag = i === 0 ? 'th scope="row"' : 'td';
1596→        var closeTag = i === 0 ? 'th' : 'td';
1597→        bHtml += '<' + tag + '>' + escapeHtml(String(cell)) + '</' + closeTag + '>';
1598→      });
1599→      bHtml += '</tr>';
1600→    });
1601→    body.innerHTML = bHtml;
1602→  }
1603→
1604→  // ── Bootstrap ──────────────────────────────────────────────────────────────
1605→  function init() {
1606→    // Try cache first for instant first paint
1607→    var cached = getCached();
1608→    if (cached) {
1609→      applyConfig(cached);
1610→    } else {
1611→      // Default trigger shown immediately while config loads
1612→      renderTrigger(null);
1613→    }
1614→    // Always fetch fresh config (async, non-blocking)
1615→    apiFetch(APP_BASE + '/api/widget-config?shop=' + encodeURIComponent(SHOP))
1616→      .then(function (resp) {
1617→        if (resp && resp.config) {
1618→          setCache(resp.config);
1619→          applyConfig(resp.config);
1620→        }
1621→      });
1622→  }
1623→
1624→  // Run after DOM is ready
1625→  if (document.readyState === 'loading') {
1626→    document.addEventListener('DOMContentLoaded', init);
1627→  } else {
1628→    init();
1629→  }
1630→
1631→})();
1632→</script>
