403→    border-radius: calc(var(--scrr-radius) - 2px);
404→    font-size: .85rem;
405→    border: 1px solid #fecaca;
406→  }
407→  .scrr-form-error[hidden] { display: none; }
408→
409→  /* Result */
410→  .scrr-result {
411→    display: flex;
412→    flex-direction: column;
413→    gap: .65rem;
414→    animation: scrFadeIn2 var(--scrr-anim) both;
415→  }
416→  .scrr-result[hidden] { display: none; }
417→  @keyframes scrFadeIn2 { from { opacity: 0; transform: translateY(6px); } to { opacity: 1; transform: none; } }
418→
419→  .scrr-result-inner { display: flex; align-items: center; gap: .85rem; }
420→  .scrr-result-badge {
421→    display: flex;
422→    flex-direction: column;
423→    align-items: center;
424→    justify-content: center;
425→    min-width: 80px;
426→    padding: .6rem .85rem;
427→    background: var(--scrr-input-bg);
428→    border: 2px solid var(--scrr-primary);
429→    border-radius: calc(var(--scrr-radius) + 2px);
430→    flex-shrink: 0;
431→  }
432→  .scrr-result-label {
433→    font-size: .7rem;
434→    font-weight: 700;
435→    text-transform: uppercase;
436→    letter-spacing: .06em;
437→    color: var(--scrr-muted);
438→  }
439→  .scrr-result-size {
440→    font-size: 2rem;
441→    font-weight: 800;
442→    color: var(--scrr-primary);
443→    line-height: 1.1;
444→  }
445→  .scrr-result-info { flex: 1; min-width: 0; }
446→  .scrr-result-msg { font-size: .88rem; color: var(--scrr-text); margin: 0 0 .3rem; }
447→
448→  .scrr-alts[hidden] { display: none; }
449→  .scrr-alts-label { font-size: .78rem; color: var(--scrr-muted); margin: 0 0 .3rem; }
450→  .scrr-alts-chips { display: flex; gap: .35rem; flex-wrap: wrap; }
451→  .scrr-alt-chip {
452→    display: inline-flex;
453→    flex-direction: column;
454→    align-items: center;
455→    padding: .25em .65em;
456→    border: 1px solid var(--scrr-border);
457→    border-radius: 100px;
458→    font-size: .78rem;
459→    color: var(--scrr-text);
460→  }
461→  .scrr-alt-conf { font-size: .68rem; color: var(--scrr-muted); }
462→
463→  .scrr-redo {
464→    align-self: flex-start;
465→    background: none;
466→    border: 1px solid var(--scrr-border);
467→    border-radius: 100px;
468→    padding: .35em .95em;
469→    font-size: .82rem;
470→    color: var(--scrr-muted);
471→    cursor: pointer;
472→    min-height: 44px;
473→    transition: border-color var(--scrr-anim), color var(--scrr-anim);
474→  }
475→  .scrr-redo:hover { border-color: var(--scrr-primary); color: var(--scrr-primary); }
476→  .scrr-redo:focus-visible {
477→    outline: 3px solid var(--scrr-primary);
478→    outline-offset: 2px;
479→  }
480→
481→  /* Footer */
482→  .scrr-powered {
483→    font-size: .72rem;
484→    color: var(--scrr-muted);
485→    text-align: center;
486→    margin: 0;
487→  }
488→  .scrr-powered-link { color: var(--scrr-muted); text-decoration: underline; }
489→  .scrr-powered-link:hover { color: var(--scrr-primary); }
490→  .scrr-powered-link:focus-visible {
491→    outline: 2px solid var(--scrr-primary);
492→    outline-offset: 2px;
493→    border-radius: 2px;
494→  }
495→
496→  @media (prefers-reduced-motion: reduce) {
497→    *, *::before, *::after {
498→      animation-duration: .01ms !important;
499→      transition-duration: .01ms !important;
500→    }
501→  }
502→</style>
