504→{%- comment -%} ══ JAVASCRIPT ══════════════════════════════════════════════ {%- endcomment -%}
505→<script>
506→(function () {
507→  'use strict';
508→
509→  var BLOCK_ID   = '{{ block_id }}';
510→  var SHOP       = '{{ shop_domain }}';
511→  var PRODUCT_ID = '{{ product_id }}';
512→  var APP_BASE   = '/apps/size-chart-recommender';
513→
514→  function $(id) { return document.getElementById(id); }
515→
516→  function apiFetch(url, opts, ms) {
517→    var ctrl = new AbortController();
518→    var t = setTimeout(function () { ctrl.abort(); }, ms || 5000);
519→    return fetch(url, Object.assign({ signal: ctrl.signal }, opts || {}))
520→      .then(function (r) { clearTimeout(t); return r.ok ? r.json() : null; })
521→      .catch(function () { clearTimeout(t); return null; });
522→  }
523→
524→  function escapeHtml(str) {
525→    var d = document.createElement('div');
526→    d.appendChild(document.createTextNode(str));
527→    return d.innerHTML;
528→  }
529→
530→  // Elements
531→  var rootEl      = $('scr-rec-root-' + BLOCK_ID);
532→  var toggle      = $('scrr-toggle-' + BLOCK_ID);
533→  var body        = $('scrr-body-' + BLOCK_ID);
534→  var disabledEl  = $('scrr-disabled-' + BLOCK_ID);
535→  var form        = $('scrr-form-' + BLOCK_ID);
536→  var heightEl    = $('scrr-height-' + BLOCK_ID);
537→  var weightEl    = $('scrr-weight-' + BLOCK_ID);
538→  var heightUnit  = $('scrr-height-unit-' + BLOCK_ID);
539→  var weightUnit  = $('scrr-weight-unit-' + BLOCK_ID);
540→  var heightErr   = $('scrr-height-err-' + BLOCK_ID);
541→  var weightErr   = $('scrr-weight-err-' + BLOCK_ID);
542→  var submitBtn   = $('scrr-submit-' + BLOCK_ID);
543→  var submitText  = submitBtn ? submitBtn.querySelector('.scrr-submit-text') : null;
544→  var spinner     = submitBtn ? submitBtn.querySelector('.scrr-spinner') : null;
545→  var formErr     = $('scrr-form-err-' + BLOCK_ID);
546→  var resultEl    = $('scrr-result-' + BLOCK_ID);
547→  var resultSize  = $('scrr-result-size-' + BLOCK_ID);
548→  var resultMsg   = $('scrr-result-msg-' + BLOCK_ID);
549→  var altsWrap    = $('scrr-alts-' + BLOCK_ID);
550→  var altsChips   = $('scrr-alts-chips-' + BLOCK_ID);
551→  var redoBtn     = $('scrr-redo-' + BLOCK_ID);
552→
553→  // Apply colors from data attributes for instant paint
554→  if (rootEl) {
555→    var p = rootEl.dataset;
556→    if (p.primaryColor)  rootEl.style.setProperty('--scrr-primary',  p.primaryColor);
557→    if (p.bgColor)       rootEl.style.setProperty('--scrr-bg',       p.bgColor);
558→    if (p.textColor)     rootEl.style.setProperty('--scrr-text',     p.textColor);
559→    if (p.borderRadius)  rootEl.style.setProperty('--scrr-radius',   p.borderRadius + 'px');
560→  }
561→
562→  // Loaded chart ID (fetched lazily on first open)
563→  var chartId = null;
564→  var chartFetched = false;
565→
566→  function fetchChartId() {
567→    if (chartFetched) return;
568→    chartFetched = true;
569→    var url = APP_BASE + '/api/size-chart?shop=' + encodeURIComponent(SHOP) + '&productId=' + encodeURIComponent(PRODUCT_ID);
570→    apiFetch(url).then(function (resp) {
571→      // api.size-chart returns { id, name, category, type, data: { headers, units, rows } }
572→      if (resp && !resp.error && resp.id && resp.data) {
573→        chartId = resp.id;
574→      }
575→    });
576→  }
577→
578→  // ── Toggle expand / collapse ────────────────────────────────────────────────
579→  var isExpanded = false;
580→
581→  if (toggle && body) {
582→    toggle.addEventListener('click', function () {
583→      isExpanded = !isExpanded;
584→      toggle.setAttribute('aria-expanded', isExpanded ? 'true' : 'false');
585→      if (isExpanded) {
586→        body.removeAttribute('hidden');
587→        // Lazy-fetch chart ID when first opened
588→        fetchChartId();
589→      } else {
590→        body.setAttribute('hidden', '');
591→      }
592→    });
593→  }
594→
595→  // ── Unit system toggle ──────────────────────────────────────────────────────
596→  if (form) {
597→    form.addEventListener('change', function (e) {
598→      if (e.target.name !== 'unit') return;
599→      var isMetric = e.target.value === 'metric';
600→      if (heightUnit) heightUnit.textContent = isMetric ? '(cm)' : '(in)';
601→      if (weightUnit) weightUnit.textContent = isMetric ? '(kg)' : '(lbs)';
602→      if (heightEl) {
603→        heightEl.min   = isMetric ? '100' : '40';
604→        heightEl.max   = isMetric ? '250' : '98';
605→        heightEl.placeholder = isMetric ? '170' : '67';
606→      }
607→      if (weightEl) {
608→        weightEl.min   = isMetric ? '30'  : '66';
609→        weightEl.max   = isMetric ? '300' : '660';
610→        weightEl.placeholder = isMetric ? '65' : '143';
611→      }
612→    });
613→  }
614→
615→  // ── Helpers ─────────────────────────────────────────────────────────────────
616→  function setFieldError(el, errEl, msg) {
617→    if (el)    el.setAttribute('aria-invalid', 'true');
618→    if (errEl) { errEl.textContent = msg; errEl.removeAttribute('hidden'); }
619→  }
620→
621→  function clearFieldError(el, errEl) {
622→    if (el)    el.removeAttribute('aria-invalid');
623→    if (errEl) { errEl.textContent = ''; errEl.setAttribute('hidden', ''); }
624→  }
625→
626→  function setFormError(msg) {
627→    if (formErr) { formErr.textContent = msg; formErr.removeAttribute('hidden'); }
628→  }
629→
630→  function clearFormError() {
631→    if (formErr) { formErr.textContent = ''; formErr.setAttribute('hidden', ''); }
632→  }
633→
634→  function setSubmitting(on) {
635→    if (!submitBtn) return;
636→    submitBtn.disabled = on;
637→    if (submitText) submitText.textContent = on ? 'Calculating\u2026' : 'Find My Size';
638→    if (spinner) {
639→      if (on) spinner.removeAttribute('hidden');
640→      else    spinner.setAttribute('hidden', '');
641→    }
642→  }
643→
644→  function trackEvent(type, extra) {
645→    var body2 = Object.assign({ shop: SHOP, eventType: type, productId: PRODUCT_ID }, extra || {});
646→    apiFetch(APP_BASE + '/api/analytics-event', {
647→      method: 'POST',
648→      headers: { 'Content-Type': 'application/json' },
649→      body: JSON.stringify(body2)
650→    }, 5000);
651→  }
652→
653→  // ── Form submit ─────────────────────────────────────────────────────────────
654→  if (form) {
655→    form.addEventListener('submit', function (e) {
656→      e.preventDefault();
657→      clearFormError();
658→      clearFieldError(heightEl, heightErr);
659→      clearFieldError(weightEl, weightErr);
660→
661→      var fd      = new FormData(form);
662→      var unit    = fd.get('unit');
663→      var height  = parseFloat(fd.get('height'));
664→      var weight  = parseFloat(fd.get('weight'));
665→      var gender  = fd.get('gender');
666→      var bodyType = fd.get('bodyType');
667→
668→      var isMetric = unit === 'metric';
669→      var valid = true;
670→
671→      if (isNaN(height) || height < (isMetric ? 100 : 40) || height > (isMetric ? 250 : 98)) {
672→        setFieldError(heightEl, heightErr,
673→          'Enter a valid height (' + (isMetric ? '100-250 cm' : '40-98 inches') + ')');
674→        valid = false;
675→      }
676→      if (isNaN(weight) || weight < (isMetric ? 30 : 66) || weight > (isMetric ? 300 : 660)) {
677→        setFieldError(weightEl, weightErr,
678→          'Enter a valid weight (' + (isMetric ? '30-300 kg' : '66-660 lbs') + ')');
679→        valid = false;
680→      }
681→      if (!valid) return;
682→
683→      if (!chartId) {
684→        setFormError('Unable to load chart data. Please refresh the page and try again.');
685→        return;
686→      }
687→
688→      setSubmitting(true);
689→
690→      apiFetch(APP_BASE + '/api/recommend', {
691→        method: 'POST',
692→        headers: { 'Content-Type': 'application/json' },
693→        body: JSON.stringify({
694→          shop: SHOP,
695→          chartId: chartId,
696→          height: height,
697→          weight: weight,
698→          unit: unit,
699→          gender: gender,
700→          bodyType: bodyType
701→        })
702→      })
703→        .then(function (resp) {
704→          setSubmitting(false);
705→          if (!resp) { setFormError('Unable to get a recommendation. Please try again.'); return; }
706→          if (resp.error) {
707→            if (resp.error.includes('not enabled')) {
708→              // Show disabled notice
709→              if (disabledEl) disabledEl.removeAttribute('hidden');
710→              if (form) form.style.display = 'none';
711→            } else {
712→              setFormError(resp.error);
713→            }
714→            return;
715→          }
716→          showResult(resp);
717→          trackEvent('recommend', { sizeChartId: chartId, size: resp.recommendedSize });
718→        })
719→        .catch(function () {
720→          setSubmitting(false);
721→          setFormError('An unexpected error occurred. Please try again.');
722→        });
723→    });
724→  }
725→
726→  function showResult(resp) {
727→    if (!resultEl) return;
728→    if (form) form.style.display = 'none';
729→    resultEl.removeAttribute('hidden');
730→    if (resultSize) resultSize.textContent = resp.recommendedSize || '?';
731→    var conf = Math.round((resp.confidence || 0) * 100);
732→    if (resultMsg) {
733→      resultMsg.textContent = conf >= 80
734→        ? 'Great fit — ' + conf + '% confidence.'
735→        : conf >= 60
736→          ? 'Good fit (' + conf + '% confidence). Also check the size chart.'
737→          : 'Best estimate (' + conf + '% confidence). Check the chart for confirmation.';
738→    }
739→    var alts = resp.alternatives || [];
740→    if (altsChips && alts.length > 0) {
741→      altsChips.innerHTML = alts.map(function (a) {
742→        return '<span class="scrr-alt-chip" role="listitem">'
743→          + escapeHtml(a.size)
744→          + '<span class="scrr-alt-conf">' + Math.round((a.confidence || 0) * 100) + '%</span>'
745→          + '</span>';
746→      }).join('');
747→      if (altsWrap) altsWrap.removeAttribute('hidden');
748→    }
749→  }
750→
751→  // Redo
752→  if (redoBtn) {
753→    redoBtn.addEventListener('click', function () {
754→      if (resultEl) resultEl.setAttribute('hidden', '');
755→      if (form) form.style.display = '';
756→      clearFormError();
757→    });
758→  }
759→
760→  // Load widget config to apply server-side color overrides
761→  (function loadConfig() {
762→    var CACHE_KEY = 'scr_config_' + SHOP;
763→    var CACHE_TTL = 5 * 60 * 1000;
764→    var cached = null;
765→    try {
766→      var raw = localStorage.getItem(CACHE_KEY);
767→      if (raw) {
768→        var obj = JSON.parse(raw);
769→        if (Date.now() - obj.ts < CACHE_TTL) cached = obj.data;
770→      }
771→    } catch (e) {}
772→
773→    function applyColors(config) {
774→      if (!config || !rootEl) return;
775→      if (config.primaryColor)    rootEl.style.setProperty('--scrr-primary',  config.primaryColor);
776→      if (config.backgroundColor) rootEl.style.setProperty('--scrr-bg',       config.backgroundColor);
777→      if (config.textColor)       rootEl.style.setProperty('--scrr-text',     config.textColor);
778→      if (config.borderRadius)    rootEl.style.setProperty('--scrr-radius',   config.borderRadius + 'px');
779→      if (config.successColor)    rootEl.style.setProperty('--scrr-success',  config.successColor);
780→      if (config.errorColor)      rootEl.style.setProperty('--scrr-error',    config.errorColor);
781→    }
782→
783→    if (cached) {
784→      applyColors(cached);
785→    }
786→
787→    apiFetch(APP_BASE + '/api/widget-config?shop=' + encodeURIComponent(SHOP))
788→      .then(function (resp) {
789→        if (resp && resp.config) {
790→          try { localStorage.setItem(CACHE_KEY, JSON.stringify({ data: resp.config, ts: Date.now() })); }
791→          catch (e) {}
792→          applyColors(resp.config);
793→          // Update heading text from server config
794→          var labelEl = toggle ? toggle.querySelector('.scrr-toggle-label') : null;
795→          if (labelEl && resp.config.buttonText) labelEl.textContent = resp.config.buttonText;
796→        }
797→      });
798→  }());
799→
800→})();
801→</script>
